pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockBlock, bytes32 hash, uint256 settleBlock) public {
        // Restrict to admissible range: lockBlock must be in the past, settleBlock after lockBlock but before typical max.
        vm.assume(lockBlock > 0 && lockBlock < block.number - 1);
        address actor = address(uint160(lockBlock)); // derive deterministic but fuzzed address, bounded by vm.assume
        // Set block to lockBlock
        vm.roll(lockBlock);
        // Fund actor with 1 ether and prank
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        // lockInGuess sets guesses[actor].block = lockBlock + 1 (reference) or +2 (bug)
        // Fuzz settleBlock: must be > lockBlock to be admissible for settle, bounded to avoid extreme future.
        vm.assume(settleBlock > lockBlock && settleBlock < lockBlock + 256);
        vm.roll(settleBlock);
        bool refSettleSuccess;
        vm.prank(actor);
        try c.settle() { refSettleSuccess = true; } catch { refSettleSuccess = false; }
        // General rule: reference settle() reverts at settleBlock == lockBlock + 1 (since block.number > guesses[actor].block 
        // requires settleBlock > lockBlock + 1). Bug sets guesses[actor].block = lockBlock + 2, so at settleBlock = lockBlock + 1,
        // condition is block.number > lockBlock + 2 → false (reverts), whereas reference condition is block.number > lockBlock + 1 → false (reverts).
        // Wait, reconsider: reference: stored = lockBlock + 1. settleBlock = lockBlock + 1 → block.number > lockBlock + 1 is false (reverts).
        // Bug: stored = lockBlock + 2. settleBlock = lockBlock + 1 → block.number > lockBlock + 2 is false (reverts) too.
        // So both revert at that block? Let's adjust: reference reverts when settleBlock <= lockBlock + 1. Bug reverts when settleBlock <= lockBlock + 2.
        // At settleBlock = lockBlock + 2, reference condition: lockBlock + 2 > lockBlock + 1 (true) → does not revert;
        // bug condition: lockBlock + 2 > lockBlock + 2 (false) → reverts. So at settleBlock = lockBlock + 2, reference succeeds, bug reverts.
        // Rule: For settleBlock = lockBlock + 2, the reference NEVER reverts, but the bug may revert.
        // Instead, we assert: if settleBlock == lockBlock + 2, the reference must succeed.
        // This is a general property: at block = storedBlock + 1, settle must succeed. The bug storedBlock is lockBlock + 2, so storedBlock + 1 = lockBlock + 3.
        // Let's derive: storeRef = lockBlock + 1, storeBug = lockBlock + 2.
        // Condition for settle success: currentBlock > storedBlock.
        // Reference: succeeds when settleBlock > lockBlock + 1.
        // Bug: succeeds when settleBlock > lockBlock + 2.
        // Therefore, for settleBlock = lockBlock + 2, reference succeeds, bug fails.
        if (settleBlock == lockBlock + 2) {
            // Reference MUST succeed (no revert). Bug will revert because block.number (lockBlock+2) > lockBlock+2 is false.
            assertTrue(refSettleSuccess);
        }
    }
}

