pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }
    function testFuzz_property(bytes32 hash, uint256 blockOffset) public {
        // Admissible: blockOffset is small enough for blockhash to work, and >0.
        vm.assume(blockOffset > 0 && blockOffset <= 256);

        // Fuzz an adversary with 1 ether to lock a guess.
        address solver = address(0x1000);
        vm.deal(solver, 1 ether);
        vm.startPrank(solver);
        c.lockInGuess{value: 1 ether}(hash);

        // Warp to the future block where the guess is settled.
        uint256 targetBlock = block.number + blockOffset;
        vm.roll(targetBlock);
        // Warp to one block after the target block.
        vm.roll(targetBlock + 1);

        uint256 balBefore = solver.balance;
        c.settle();
        uint256 balAfter = solver.balance;
        vm.stopPrank();

        // If the guess was correct (hash == blockhash(targetBlock) and answer != 0),
        // the transfer should have happened. We assert a universal property:
        // If a transfer happened (balAfter > balBefore), then the increase must be exactly 2 ether.
        // In the buggy version, no increase happens, so if the guess was correct the property
        // "increase is never zero" is violated. Actually we need a property that always holds on correct
        // but fails on bug. Correct always transfers 2 ether or 0. Bug transfers 0 always.
        // Property: if solver gains ether after settle, the gain must be exactly 2 ether.
        // On correct, gain can be 2 or 0. On bug, gain is always 0.
        // That property doesn't fail on bug (bug never gives gain).
        // We need a property that says "if the blockhash matches the guess, then balancing property".
        // Simpler: call settle, check c's balance. After settle, c's balance should be 0 if a correct guess
        // paid out 2 ether (total in = 1 constructor + 1 lockIn = 2 ether, pay out 2 ether -> 0).
        // If guess wrong, c keeps 2 ether. In bug, even correct guess keeps 2 ether.
        // So property: after settle, if balance of c is 0, that is fine; but if balance is >0, it must be 2 ether.
        // That holds for correct: wrong guess -> 2 ether, correct guess -> 0 ether.
        // Bug: correct guess -> 2 ether (still holds). No difference.

        // Better: check that if a correct guess happened, solver.balance increased by exactly 2 ether.
        // We can't know if guess was correct, but we can assert: (balAfter - balBefore) is either 0 or 2 ether.
        // In buggy, after correct guess, balAfter - balBefore = 0, but the property still holds (0 is allowed).
        // So we need a property that distinguishes 0 vs 2 ether for correct guesses.
        // Use the contract's own storage: after settle, guesses[solver].block is set to 0.
        // If the guess was correct, c's balance drops by 2 ether. We can read address(c).balance.
        // Let bal_c_before = address(c).balance before settle; bal_c_after = address(c).balance after.
        // Property: bal_c_before - bal_c_after is either 0 or 2 ether. That holds for both.

        // Final approach: The invariant "solver's balance never changes by exactly 0 ether when the guess is correct"
        // is weird. Instead, we assert: after settle, if the blockhash answer is not zero and equals the hash,
        // then solver must have received exactly 2 ether. But we can't check answer externally without using
        // blockhash again. We can compute it: bytes32 answer = blockhash(targetBlock);
        // That is available because targetBlock is within 256 blocks.
        bytes32 answer = blockhash(targetBlock);
        if (answer != 0 && hash == answer) {
            // In correct version, solver must gain exactly 2 ether.
            // In buggy version, solver gains 0 ether, so this assertion fails.
            assertEq(balAfter - balBefore, 2 ether);
        } else {
            // If guess not correct, gain must be 0.
            assertEq(balAfter - balBefore, 0);
        }
    }
}

