contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }
    function testFuzz_property(bytes32 guessHash, uint256 blockJump) public {
        // restrict blockJump so block.number + blockJump is in the future but does not overflow
        vm.assume(blockJump > 0 && blockJump < type(uint256).max - block.number);
        // the contract already has 1 ether from construction, fund user with 2 ether so they can make a lockInGuess and have 1 extra ether to keep alive
        address user = address(0x1234);
        vm.deal(user, 2 ether);
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(guessHash);
        // advance blocks so settle is callable
        vm.roll(block.number + blockJump);
        // capture contract balance before settle
        uint256 balanceBefore = address(c).balance;
        vm.prank(user);
        c.settle();
        uint256 balanceAfter = address(c).balance;
        // if the guess matched and the blockhash was nonzero, the contract must have transferred 2 ether away, otherwise balance stays unchanged (1 ether)
        // the reference C satisfies: balanceAfter <= balanceBefore (contract balance never increases from settle)
        // and if a reward was paid, balanceAfter == balanceBefore - 2 ether; mutant pays 0 ether so balanceAfter == balanceBefore
        // general invariant: contract balance after settle is either balanceBefore (no reward) or balanceBefore - 2 ether (reward paid)
        // mutant breaks this by never decreasing balance, so when a reward is triggered, balanceAfter == balanceBefore instead of balanceBefore - 2 ether
        // but we need a property that always holds for reference and sometimes fails for mutant:
        // In reference: (balanceAfter == balanceBefore - 2 ether) XOR (balanceAfter == balanceBefore) is always true.
        // In mutant: when reward is triggered, balanceAfter == balanceBefore (not balanceBefore - 2 ether), so the xor condition becomes false because both sides could be false? Actually for mutant, reward triggered => balanceAfter == balanceBefore, so (balanceAfter == balanceBefore - 2 ether) is false, (balanceAfter == balanceBefore) is true, xor is true. So xor invariant still holds. Need a different invariant.
        // Better: In reference, it's impossible that a correct guess results in balanceAfter == balanceBefore (since payout occurs).
