    }

    function testFuzz_property(bytes32 guessHash, uint256 advanceBlocks, uint256 fuzzBlock) public {
        // Restrict block advancement to a reasonable range while keeping the search wide
        advanceBlocks = bound(advanceBlocks, 0, 10);
        // fuzzer picks an arbitrary future block; we just set the current number relative to it.
        // We ensure that fuzzBlock is in the future relative to the block after lockInGuess.
        // This leaves the fuzzer free to choose any starting point up to a large maximum,
        // and the mutant triggers when guess.block is >= current block (future or equal).
        fuzzBlock = bound(fuzzBlock, advanceBlocks + 1, 1_000_000);

        // Move to a known block and grab the deployer as the player
        vm.roll(fuzzBlock);
        address player = makeAddr("player");
        vm.deal(player, 10 ether);

        // Player locks a guess
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance at least one block so that blockhash can be non-zero, but still
        // before the guessed block number. The fuzzer controls how many blocks we advance.
        // After advance, current block is fuzzBlock + advanceBlocks + 1.
        // The guessed block (from lockInGuess) is fuzzBlock + 1.
        // With advanceBlocks >= 1 we satisfy block.number > guess.block for the reference,
        // but with advanceBlocks == 0 we make block.number == guess.block (or < guess.block),
        // which is only allowed in the mutant.
        vm.roll(fuzzBlock + advanceBlocks + 1);

        bool refOk;
        try c.settle() {
            refOk = true;
        } catch {
            refOk = false;
        }

        // The reference always satisfies: if block.number > guesses[player].block
        // the call never reverts. The mutant removes this guard, so it can revert
        // or succeed for a future block. The invariant we check is simpler:
        // after settle, the player's block entry MUST be 0 (resets always happen),
        // AND a successful settle (non-revert) can ONLY happen when block.number
        // is strictly greater than the guessed block.
        // In the reference, when block.number <= guess.block the require fails -> revert,
        // so refOk is false; when it is strictly greater, refOk is true.
        // In the mutant, the require is missing, so refOk could be true even when
        // block.number <= guess.block. Thus we assert that if refOk is true, then
        // block.number was indeed > guessed block. This property holds for all
        // inputs in the reference, but the mutant breaks it for some input.

        // We derive the guessed block indirectly: it is fuzzBlock + 1.
        // (Alternatively, we could use a public getter for guesses, but the struct
        // is internal and guesses mapping has no auto getter. The invariant is
        // expressed in terms of the underlying block number we set, which is
        // always in sync with the state.)

        uint256 guessedBlock = fuzzBlock + 1;
        uint256 currentBlock = block.number;

        // The rule: if settle did not revert, then currentBlock > guessedBlock.
        // Reference always holds; mutant violates it when advanceBlocks == 0.
        assertTrue(!refOk || currentBlock > guessedBlock);
    }
}

