        vm.prank(player);
        c.lockInGuess{value: valueSent}(guessHash);
        vm.roll(block.number + blockOffset + 1);
        vm.prank(player);
        c.settle();
        uint256 endBalance = address(c).balance;
        bool recovered = false;
        try c.settle() { recovered = true; } catch { recovered = false; }
        bool paidOut = endBalance < startBalance;
        assertTrue(!paidOut || (paidOut && !recovered));
    }
}

